#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LivingTable.Chess;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace LivingTable.Editor {
 public static class CaptureContinueTests {
  static int count,stage;static double deadline;static ChessTable table;static string id,key;static ChessPosition captured;
  static void Check(bool ok,string label){count++;if(!ok)throw new Exception("CAPTURE CONTINUE: "+label);}
  static void Invoke(string name,params object[] args)=>typeof(ChessTable).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(table,args);
  static void Set(string name,object value)=>typeof(ChessTable).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(table,value);
  static void Corners(Vector3 offset){table.BeginFourCorners();foreach(var p in new[]{new Vector3(-.28f,.8f,-.28f),new Vector3(.28f,.8f,-.28f),new Vector3(.28f,.8f,.28f),new Vector3(-.28f,.8f,.28f)})Check(table.SelectBoardCorner(p+offset),"Corner accepted");table.ConfirmQuickGrid();Invoke("CompleteKingSizing");}
  public static void Run(){SessionState.SetString("CaptureContinueRoot",Path.GetFullPath("Logs/capture-continue-"+Guid.NewGuid().ToString("N")));EditorSceneManager.OpenScene(ChessContestRelease.DesktopScene);SessionState.SetBool("CaptureContinueTests",true);EditorApplication.EnterPlaymode();}
  [InitializeOnLoadMethod]static void Resume(){if(!SessionState.GetBool("CaptureContinueTests",false))return;GameSessionStore.TestRoot=SessionState.GetString("CaptureContinueRoot","");deadline=EditorApplication.timeSinceStartup+150;EditorApplication.update+=Tick;}
  static void Tick(){try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Capture continuity timeout");if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;
   if(stage==0){table=UnityEngine.Object.FindFirstObjectByType<ChessTable>();if(table?.Vision==null)return;table.GetComponent<ChessMetaVision>().Required=true;table.QuickPlay();
    var hud=UnityEngine.Object.FindObjectsByType<TableFacingPanel>(FindObjectsSortMode.None).First(x=>x.name=="Floating setup instructions"&&x.gameObject.activeInHierarchy);Check(hud.InstructionView&&Vector3.Distance(hud.transform.position,Camera.main.transform.position)<.75f,"Setup guidance floats directly in view");var menu=(Transform)typeof(ChessTable).GetField("panelMenu",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(table);var ray=new Ray(Camera.main.transform.position,menu.position-Camera.main.transform.position);Check(table.PointAtMenu(ray,true)&&table.StandardMenuOpen,"Point-and-pinch reaches distant menu");table.OpenStandardMenu();
    Check(table.CaptureInProgress&&table.Physical&&!table.Playing,"Quick Play starts physical capture, not a fresh virtual game");Check(table.Message.ToLowerInvariant().Contains("look down")&&table.VisiblePieceCount==0,"Look-down instruction without guessed pieces");id=table.SessionId;Check(JsonUtility.FromJson<ChessTable.SessionState>(GameSessionStore.Load(id).payload).draft,"Initial capture is a Continue checkpoint");
    table.PreviewMetricAlignment(new ChessSurfaceSolver.Estimate{center=new Vector3(0,.8f,0),size=.56f,rotation=Quaternion.identity,corners=35,rmsPixels=.8f,rmsMeters=.002f,source="synthetic fixture",valid=true});Check(!table.Vision.Checking&&!table.Aligned&&table.SelectingCorners,"Quick Play metric preview requires all four corners");Corners(Vector3.zero);Check(table.Vision.Checking&&!table.Playing,"Confirmed corners and sizing precede piece mapping");table.Vision.CellProgress[0]=1;table.Vision.CellProgress[1]=2;table.Vision.CellProgress[2]=3;table.SendMessage("Update");Check(table.GetComponentsInChildren<Transform>().Count(x=>x.name.StartsWith("Scan ")&&x.gameObject.activeInHierarchy)==3,"Each evaluated square has visible scan feedback");Check(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Any(x=>x.name=="Scan loading spinner"&&x.gameObject.activeInHierarchy),"Active scan shows loading spinner");table.Vision.CancelScan();
    captured=ChessPosition.FromFen("rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2");table.ReceiveLayout(captured.Board,"Synthetic observed midgame");Check(table.SetupReviewing&&table.VisiblePieceCount==32,"Observed midgame is shown for validation");
    Invoke("ConfirmLayout");Check(!table.SizingKing&&!table.SelectingCorners,"Captured layout proceeds to turn choice after confirmed corners and sizing");Set("quickPhase",1);Set("alignStage",8);table.ShowHome();Check(table.HomeScreen,"Capture can safely leave to home");table.ContinueLatest();Check(table.SessionId==id&&table.CaptureInProgress&&table.SetupReviewing&&!table.Aligned,"Continue restores draft and requires fresh physical registration");
    Invoke("ConfirmLayout");Check(table.SelectingCorners,"Accepting the captured position proceeds to four corners");Corners(Vector3.zero);Check(!table.Playing,"King sizing never auto-starts play");Set("turnChosen",true);var position=(ChessPosition)typeof(ChessTable).GetField("setupPosition",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(table);position.Side=1;position.Rights=15;Invoke("ConfirmTurn");
    Check(table.GetComponentsInChildren<TableButtonVisual>().Count(x=>x.name=="START GAME button")==1,"One final START GAME action");Capture();Invoke("StartObservedGame");
    Check(table.VirtualSafetyOpen&&table.Physical&&!table.Playing&&table.SessionMenuOpen,"Capture waits for clear-space acknowledgement");Capture("Logs/Virtual-safety-011.png");table.CancelVirtualSafety();Check(!table.VirtualSafetyOpen&&!table.Playing&&table.Physical,"Cancel stays physical and retains draft");Invoke("StartObservedGame");table.ConfirmVirtualSafety();
    Check(table.Playing&&!table.Physical&&!table.TwoPlayers&&!table.CaptureInProgress,"Accepted capture starts virtual AI play");Check(table.SessionId==id&&table.Match.Position.Board.SequenceEqual(captured.Board),"Same save identity and exact captured pieces");Check(table.Match.Position.Rights==15&&table.Match.Position.Side==1,"Explicit turn and rights preserved");Check(table.Unverified,"Unknown pre-capture history remains labeled");Check(table.GetComponentsInChildren<Transform>().Count(x=>x.name.EndsWith("captured pieces"))==2,"Both captured-piece displays appear outside board");
    var state=table.CaptureSession();Check(state.registration!=null&&state.registration.corners.Length==4&&Mathf.Abs(state.registration.size-.56f)<.001f,"Physical geometry stored per save");
    var move=table.Match.Position.LegalMoves().Single(m=>m.From==6&&m.To==21);Check(table.Play(move),"Human can move from captured midgame");stage=1;
   }else if(stage==1){if(table.Busy||table.Match.Position.Ply<2)return;Check(table.Match.Position.Side==1,"AI plays opposite the user and returns turn");key=table.Match.Position.Key();id=table.SessionId;Check(table.CaptureSession().match.moves.Length==2,"Both new moves retained after capture");
    table.OpenStandardMenu();Invoke("MenuHome");var stored=JsonUtility.FromJson<ChessTable.SessionState>(GameSessionStore.Load(id).payload);Check(!stored.paused,"Opening the menu does not persist a false pause");Check(!stored.draft&&stored.registration?.corners.Length==4&&stored.match.moves.Length==2,"Leaving saves history and registration together");table.ContinueLatest();Check(table.Playing&&!table.Physical&&table.SessionId==id&&table.Match.Position.Key()==key,"Continue resumes exact virtual midgame");
    table.SwitchSurface();Check(table.Physical&&table.Recovering&&!table.Aligned,"Physical return holds play before reconstruction");Corners(new Vector3(.2f,0,.1f));Check(table.Recovering&&table.Vision.Checking,"Accepted geometry begins saved-board verification");Check(table.Match.Position.Key()==key&&table.SessionId==id,"Physical setup cannot rewrite the saved game");
    var wrong=table.Match.Position.After(table.Match.Position.LegalMoves().First());var observation=new ChessObservationGate.Observation{revision=table.Version,cells=Enumerable.Range(0,64).Select(s=>new ChessObservationGate.Cell{square=ChessMove.Square(s),piece=ChessObservationGate.Piece(wrong.Board[s])}).ToArray()};Check(!ChessObservationGate.AcceptBoard(table.Match.Position,table.Version,observation,out _),"A legal but different physical position is rejected");
    Check(table.AcceptRecovery(table.Version,true)&&!table.Recovering,"Synthetic exact-board verification returns control");Check(table.Match.Position.Key()==key&&table.CaptureSession().match.moves.Length==2,"Reconciliation does not consume or invent a move");table.SwitchSurface();Check(table.VirtualSafetyOpen&&table.Physical&&table.Match.Position.Key()==key,"Handoff holds physical state and saved position until acknowledgement");table.CancelVirtualSafety();Check(table.Physical&&!table.VirtualSafetyOpen,"Canceled handoff stays physical");table.SwitchSurface();table.ConfirmVirtualSafety();Check(!table.Physical&&!table.VirtualSafetyOpen&&table.Match.Position.Key()==key,"Confirmed handoff preserves exact position");var captureMatch=new ChessMatch();foreach(var pair in new[]{new[]{12,28},new[]{51,35},new[]{28,35}}){var m=captureMatch.Position.LegalMoves().Single(x=>x.From==pair[0]&&x.To==pair[1]);captureMatch.Play(m);}Check(ChessTable.CapturedSinceStart(captureMatch.Capture()).SequenceEqual(new[]{-1}),"Captured display records actual captured color and type");Check(ChessTable.MissingBeforeStart(captureMatch.Capture(),-1)==0,"New game invents no earlier captures");var ep=new ChessMatch(ChessPosition.FromFen("4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1"));ep.Play(ep.Position.LegalMoves().Single(x=>x.EnPassant));Check(ChessTable.CapturedSinceStart(ep.Capture()).SequenceEqual(new[]{-1}),"En passant appears in captured display");Check(ChessTable.MissingBeforeStart(ep.Capture(),-1)==14,"Scanned midgame missing pieces remain unknown-type counts");table.NewGame();table.Configure(false,true,1);table.StartGame();typeof(ChessTable).GetProperty("Match").SetValue(table,captureMatch);Invoke("DrawScene");Capture("Logs/Captured-trays-011.png");table.NewGame();Finish(0,"CAPTURE_CONTINUE_TESTS_PASSED "+count);}
  }catch(Exception e){Finish(1,e.ToString());}}
  static void Capture(string output="Logs/Capture-start-011.png"){var camera=Camera.main;camera.transform.position=table.transform.position+new Vector3(0,.7f,-.9f);camera.transform.LookAt(table.transform.position+Vector3.up*.10f);table.SendMessage("Update");foreach(var panel in UnityEngine.Object.FindObjectsByType<TableFacingPanel>(FindObjectsSortMode.None))panel.FaceViewer();var rt=new RenderTexture(1600,1200,24);camera.targetTexture=rt;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1600,1200,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1200),0,0);image.Apply();File.WriteAllBytes(output,image.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;UnityEngine.Object.Destroy(image);UnityEngine.Object.Destroy(rt);}
  static void Finish(int code,string message){SessionState.SetBool("CaptureContinueTests",false);EditorApplication.update-=Tick;if(code==0){File.WriteAllText("Builds/Capture-continue-tests.txt",count+" synthetic capture/save/virtual-AI/physical-recovery checks passed. Camera and headset registration accuracy remain unverified.");Debug.Log(message);}else Debug.LogError(message);EditorApplication.Exit(code);}
 }
}
#endif
